// 값에 시각과 작성자를 함께 붙이면 병합 규칙이 생긴다
function merge(a, b) {
  if (a.t !== b.t) return a.t > b.t ? a : b;
  return a.by > b.by ? a : b;      // 동시각이면 id 로 결정 (누구나 같은 답)
}
// 어느 순서로 합쳐도 결과가 같다 → 동기화가 단순해진다

